  "name": "http-status-server",
  "version": "1.0.0",
  "description": "Node.js HTTP server backed by a lookup table of HTTP status codes and reason phrases",
  "type": "module",
  "main": "src/server.js",
  "exports": {
    ".": "./src/server.js",
