import http from "node:http";
import { pathToFileURL } from "node:url";
import { STATUS_CODES, getReasonPhrase, isStatusCode } from "./status-codes.js";

const EMPTY_BODY_CODES = new Set([204, 205, 304]);

function sendJson(res, statusCode, payload) {
  const body = JSON.stringify(payload);
  res.writeHead(statusCode, {
    "Content-Type": "application/json; charset=utf-8",
    "Content-Length": Buffer.byteLength(body),
  });
  res.end(body);
}

export function requestHandler(req, res) {
  const { pathname } = new URL(req.url, `http://${req.headers.host ?? "localhost"}`);

  if (req.method === "GET" && pathname === "/health") {
    return sendJson(res, 200, { status: 200, reason: getReasonPhrase(200) });
  }

  if (req.method === "GET" && pathname === "/status") {
    return sendJson(res, 200, STATUS_CODES);
  }

  const match = /^\/status\/(\d{3})$/.exec(pathname);
  if (req.method === "GET" && match) {
    const code = Number(match[1]);

    if (!isStatusCode(code)) {
      return sendJson(res, 404, { error: `Unknown status code: ${match[1]}` });
    }
    if (code < 200 || code > 599) {
      return sendJson(res, 400, { error: `Status code ${code} cannot be sent as a response` });
    }
    if (EMPTY_BODY_CODES.has(code)) {
      res.writeHead(code);
      return res.end();
    }
    return sendJson(res, code, { status: code, reason: getReasonPhrase(code) });
  }

  return sendJson(res, 404, { status: 404, reason: getReasonPhrase(404) });
}

export function createServer() {
  return http.createServer(requestHandler);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const port = Number(process.env.PORT) || 3000;
  const server = createServer();
  server.listen(port, () => {
    console.log(`HTTP server listening on http://localhost:${server.address().port}`);
  });
}

import { test } from "node:test";
import assert from "node:assert/strict";
import {
  STATUS_CODES,
  getReasonPhrase,
  getStatusCode,
  isStatusCode,
} from "../src/status-codes.js";

test("maps well-known codes to their reason phrases", () => {
  assert.equal(getReasonPhrase(200), "OK");
  assert.equal(getReasonPhrase(301), "Moved Permanently");
  assert.equal(getReasonPhrase(404), "Not Found");
  assert.equal(getReasonPhrase(500), "Internal Server Error");
});

test("getReasonPhrase accepts numeric strings", () => {
  assert.equal(getReasonPhrase("418"), "I'm a Teapot");
});

test("getReasonPhrase returns undefined for unknown codes", () => {
  assert.equal(getReasonPhrase(999), undefined);
});

test("getStatusCode performs the reverse lookup", () => {
  assert.equal(getStatusCode("No Content"), 204);
  assert.equal(getStatusCode("Not a real phrase"), undefined);
});

test("isStatusCode validates known codes", () => {
  assert.equal(isStatusCode(200), true);
  assert.equal(isStatusCode("418"), true);
  assert.equal(isStatusCode(999), false);
  assert.equal(isStatusCode("nope"), false);
});

test("lookup table is frozen", () => {
  assert.equal(Object.isFrozen(STATUS_CODES), true);
});

import { test, before, after } from "node:test";
import assert from "node:assert/strict";
import { createServer } from "../src/server.js";

let server;
let baseUrl;

before(async () => {
  server = createServer();
  await new Promise((resolve) => server.listen(0, resolve));
  baseUrl = `http://localhost:${server.address().port}`;
});

after(() => new Promise((resolve) => server.close(resolve)));

test("GET /health returns 200 OK", async () => {
  const res = await fetch(`${baseUrl}/health`);
  assert.equal(res.status, 200);
  assert.deepEqual(await res.json(), { status: 200, reason: "OK" });
});

test("GET /status returns the full lookup table", async () => {
  const res = await fetch(`${baseUrl}/status`);
  assert.equal(res.status, 200);
  const body = await res.json();
  assert.equal(body["200"], "OK");
  assert.equal(body["404"], "Not Found");
  assert.equal(body["503"], "Service Unavailable");
});

test("GET /status/:code mirrors the code and reason phrase", async () => {
  const res = await fetch(`${baseUrl}/status/404`);
  assert.equal(res.status, 404);
  assert.deepEqual(await res.json(), { status: 404, reason: "Not Found" });
});

test("GET /status/:code with an unknown code returns 404", async () => {
  const res = await fetch(`${baseUrl}/status/999`);
  assert.equal(res.status, 404);
});

test("bodyless status codes return an empty body", async () => {
  const res = await fetch(`${baseUrl}/status/204`);
  assert.equal(res.status, 204);
  assert.equal(await res.text(), "");
});

test("unknown routes return 404", async () => {
  const res = await fetch(`${baseUrl}/does-not-exist`);
  assert.equal(res.status, 404);
});

